// @ts-nocheck
// Account Executive — Sales Decisions V1.2 ("does this person have the raw material to become a great seller if Peak
// teaches them the process?"). 34 single-pick scenarios across six categories, one construct per item, experience-neutral.
// Transcribed from Peak's October 2026 brief. Points 0–4 in half steps are stored ×25 (4.0 → 100 … 0.5 → 12).
// Role-risk options are flagged at critical severity regardless of points. Failure-profile reads create interview
// probes only — they never change a score. Eight unscored Manager Insight questions close the assessment.
const PTS = { 4: 100, 3.5: 88, 3: 75, 2.5: 62, 2: 50, 1.5: 38, 1: 25, 0.5: 12, 0: 0 };
const LABEL = { bench: "Benchmark", strong: "Strong / effective alternative", dev: "Developmental concern", know: "Knowledge / experience gap", judg: "Judgment concern", risk: "Behavioral / role risk" };
// ae(id, category, title, [construct, main signal], stem, options, why, miss, probe, notes?)
// option: [pts, text, cls, sub, reason, { flag?, positive?, profile? }]
const ae = (id, comp, title, meta, text, opts, why, miss, probe, notes) => ({
  id, comp, kind: "scenario", title, construct: meta[0], itemType: "Scenario · single pick", mainSignal: meta[1], text, why, miss, probe,
  calibrate: (notes && notes.calibrate) || "", gameability: (notes && notes.gameability) || "",
  opts: opts.map(([pts, t, cls, sub, reason, x], i) => ({ i, pts, score: PTS[pts], text: t, cls, interp: LABEL[cls] + (sub ? " \u00b7 " + sub : ""), reason, flag: (x && x.flag) || null, positive: (x && x.positive) || null, profile: (x && x.profile) || null, sev: cls === "risk" ? "critical" : null })),
});

